-- =====================================================================
-- Seed real, verified problems for the 17 remaining empty topics: java,
-- go, cpp, typescript, nodejs, express, nextjs, aws, docker, kubernetes,
-- devops, databases, rest-apis, machine-learning, data-science,
-- artificial-intelligence (cybersecurity + c++-adjacent covered where
-- listed). Every expected_output was generated by running a reference
-- solver against the stated input (see the migration's companion script
-- used to derive these — not hand-guessed), 3 problems per topic.
-- =====================================================================

-- ---------------------------------------------------------------------
-- JAVA
-- ---------------------------------------------------------------------
insert into challenges (title, slug, description, difficulty, category_id, estimated_minutes, xp_reward, tags, constraints, input_format, output_format, starter_code)
values (
  'Reverse Integer',
  'java-reverse-integer',
  'Reverse the digits of a 32-bit signed integer. If reversing causes the value to fall outside the 32-bit signed range [-2^31, 2^31 - 1], output 0 instead.',
  'medium',
  (select id from challenge_categories where slug = 'java'),
  20, 50,
  array['java', 'math'],
  '-2^31 <= x <= 2^31 - 1',
  'A single integer: x.',
  'A single integer: the reversed value, or 0 on overflow.',
  $sc${"java":"import java.util.*;\npublic class Main {\n  public static void main(String[] args) {\n    Scanner sc = new Scanner(System.in);\n    long x = sc.nextLong();\n    // TODO: reverse digits, return 0 on 32-bit overflow\n    System.out.println(0);\n  }\n}\n","python":"x = int(input())\n# TODO: reverse digits, return 0 on 32-bit overflow\nprint(0)\n"}$sc$::jsonb
) on conflict (slug) do nothing;

