  'Space-separated labels in execution order.',
  $sc${"javascript":"const lines = require('fs').readFileSync(0, 'utf8').trim().split('\\n');\n// TODO: bucket into sync / microtask / macrotask (sorted by ms) and concatenate\nconsole.log('');\n"}$sc$::jsonb
) on conflict (slug) do nothing;

